AxiosHeaders.js
import parseHeaders from '../../../lib/helpers/parseHeaders';

describe('helpers::parseHeaders', function () {
  it('should parse headers', function () {
    const date = new Date();
    const parsed = parseHeaders(
      'Date: ' + date.toISOString() + '\n' +
      'Content-Type: application/json\n' +
      'Connection: keep-alive\n' +
      'Transfer-Encoding: chunked'
    );

    expect(parsed['date']).toEqual(date.toISOString());
    expect(parsed['content-type']).toEqual('application/json');
    expect(parsed['connection']).toEqual('keep-alive');
    expect(parsed['transfer-encoding']).toEqual('chunked');
  });

  it('should use array for set-cookie', function() {
    const parsedZero = parseHeaders('');
    const parsedSingle = parseHeaders(
      'Set-Cookie: key=val;'
    );
    const parsedMulti = parseHeaders(
      'Set-Cookie: key=val;\n' +
      'Set-Cookie: key2=val2;\n'
    );

    expect(parsedZero['set-cookie']).toBeUndefined();
    expect(parsedSingle['set-cookie']).toEqual(['key=val;']);
    expect(parsedMulti['set-cookie']).toEqual(['key=val;', 'key2=val2;']);
  });

  it('should handle duplicates', function() {
    const parsed = parseHeaders(
      'Age: age-a\n' + // age is in ignore duplicates blocklist
      'Age: age-b\n' +
      'Foo: foo-a\n' +
      'Foo: foo-b\n'
    );

    expect(parsed['age']).toEqual('age-a');
    expect(parsed['foo']).toEqual('foo-a, foo-b');
  });
});
import assert from 'assert';
import http from 'http';
import axios from '../../../index.js';

describe('issues', function () {
  describe('4999', function () {
    it('should not fail with query parsing', async function () {
      const {data} = await axios.get('https://postman-echo.com/get?foo1=bar1&foo2=bar2');

      assert.strictEqual(data.args.foo1, 'bar1');
      assert.strictEqual(data.args.foo2, 'bar2');
    });
  });

  describe('5028', function () {
    it('should handle set-cookie headers as an array', async function () {
      const cookie1 = 'something=else; path=/; expires=Wed, 12 Apr 2023 12:03:42 GMT; samesite=lax; secure; httponly';
      const cookie2 = 'something-ssr.sig=n4MlwVAaxQAxhbdJO5XbUpDw-lA; path=/; expires=Wed, 12 Apr 2023 12:03:42 GMT; samesite=lax; secure; httponly';

      const server = http.createServer((req, res) => {
            //res.setHeader('Set-Cookie', 'my=value');
            res.setHeader('Set-Cookie', [cookie1, cookie2]);
            res.writeHead(200);
            res.write('Hi there');
            res.end();
          }).listen(0);

      const request = axios.create();

      request.interceptors.response.use((res) => {
        assert.deepStrictEqual(res.headers['set-cookie'], [
          cookie1, cookie2
        ]);
      });

      try {
        await request({url: `http://localhost:${server.address().port}`});
      } finally {
        server.close()
      }
    });
  });
});

